insert into public.categories (slug, name, description, image_url, sort_order) values ('tui-xach-giay', 'Túi xách giấy', 'Túi giấy kraft và giấy couche cán màng, quai xoắn giấy hoặc quai dẹt, in theo yêu cầu. Dùng làm túi đựng hàng thời trang, mỹ phẩm, quà tặng và túi mua sắm bán lẻ.', '/assets/images/thumbs/product-range-img.png', 4)
