insert into public.categories (slug, name, description, image_url, sort_order) values ('hop-qua-tang', 'Hộp quà tặng cao cấp', 'Hộp quà tặng nắp rời hoặc nắp từ tính, giấy mỹ thuật hoặc bồi carton, gia công ép kim và phủ UV theo yêu cầu. Dùng làm hộp quà Tết, quà doanh nghiệp và quà tặng sự kiện.', '/assets/images/thumbs/product-range-img.png', 5)
