insert into public.categories (slug, name, description, image_url, sort_order) values ('tem-nhan-decal', 'Tem, nhãn, decal', 'Tem nhãn decal giấy, decal nhựa trong và decal kim loại, cắt bế theo khuôn hoặc theo cuộn. Dùng làm tem nhãn sản phẩm, tem bảo hành và tem niêm phong.', '/assets/images/thumbs/product-range-img.png', 6)
