insert into public.categories (slug, name, description, image_url, sort_order) values ('catalogue-brochure', 'Catalogue & brochure', 'Catalogue và brochure in offset nhiều trang, gia công đóng ghim hoặc keo gáy. Dùng làm catalogue giới thiệu sản phẩm, brochure công ty và profile doanh nghiệp.', '/assets/images/thumbs/product-range-img.png', 7)
  on conflict (slug) do update set name = excluded.name, description = excluded.description, image_url = excluded.image_url, sort_order = excluded.sort_order;
insert into public.categories (slug, name, description, image_url, sort_order) values ('danh-thiep', 'Danh thiếp (name card)', 'Danh thiếp giấy Bristol hoặc Ivory định lượng dày, cán màng bóng/mờ hoặc ép kim theo yêu cầu. Dùng làm danh thiếp cá nhân và name card doanh nghiệp.', '/assets/images/thumbs/product-range-img.png', 8)
