insert into public.categories (slug, name, description, image_url, sort_order) values ('to-roi-poster', 'Tờ rơi & poster', 'Tờ rơi và poster in offset nhiều khổ giấy, cán màng hoặc phủ UV theo yêu cầu. Dùng làm tờ rơi quảng cáo, poster sự kiện và ấn phẩm truyền thông.', '/assets/images/thumbs/product-range-img.png', 9)
