insert into public.categories (slug, name, description, image_url, sort_order) values ('lich-tet', 'Lịch Tết', 'Lịch Tết các loại: lịch bloc, lịch treo tường, lịch để bàn và lịch sổ tay, in offset theo yêu cầu. Dùng làm quà tặng Tết cho khách hàng và đối tác.', '/assets/images/thumbs/product-range-img.png', 10)
