insert into public.categories (slug, name, description, image_url, sort_order) values ('bao-li-xi', 'Bao lì xì', 'Bao lì xì in logo doanh nghiệp, giấy mỹ thuật ép kim hoặc phủ nhũ vàng, đóng set theo bộ, in offset theo yêu cầu. Dùng làm quà tặng Tết cho nhân viên, khách hàng và đối tác.', '/assets/images/thumbs/product-range-img.png', 11)
  on conflict (slug) do update set name = excluded.name, description = excluded.description, image_url = excluded.image_url, sort_order = excluded.sort_order;
insert into public.categories (slug, name, description, image_url, sort_order) values ('an-pham-van-phong', 'Ấn phẩm văn phòng', 'Ấn phẩm văn phòng: giấy tiêu đề, phong bì, bìa kẹp hồ sơ và sổ tay công ty, in offset theo bộ nhận diện thương hiệu. Dùng cho hoạt động văn phòng và giao dịch hàng ngày.', '/assets/images/thumbs/product-range-img.png', 12)
