insert into public.categories (slug, name, description, image_url, sort_order) values ('thung-carton', 'Thùng carton', 'Thùng carton 3 lớp hoặc 5 lớp sóng B/C chịu tải, dùng đóng gói vận chuyển hàng hoá số lượng lớn, xuất khẩu và lưu kho — khác thùng COD chuyên ship lẻ.', '/assets/images/thumbs/product-range-img.png', 13)
