-- ------------------------------- services -------------------------------
insert into public.services (slug, name, summary, description, icon, image_url, sort_order) values ('in-offset', 'In offset', 'In 4 màu CMYK chuẩn màu, sắc nét, tối ưu chi phí khi in số lượng lớn. Dùng cho catalogue, brochure, tờ rơi, danh thiếp, lịch Tết, hộp giấy cao cấp.', '<p>In offset là kỹ thuật chủ lực cho các ấn phẩm cần độ chuẩn màu cao và số lượng lớn. Mực được truyền từ bản kẽm qua tấm cao su rồi mới lên giấy, nhờ đó hình ảnh sắc nét, màu ổn định giữa các tờ in trong cùng một lệnh.</p><h3>Ứng dụng</h3><ul><li>Catalogue, brochure, profile công ty</li><li>Tờ rơi, poster, standee giấy</li><li>Danh thiếp (name card) 250–400gsm</li><li>Lịch bloc, lịch treo tường, lịch để bàn, lịch sổ tay</li><li>Hộp giấy bồi Duplex cao cấp, hộp quà tặng</li></ul><h3>Quy cách thường dùng</h3><ul><li>Giấy: Couche, Bristol, Ivory, Duplex, giấy mỹ thuật</li><li>Định lượng phổ biến: 200–350gsm cho bao bì, 210–250gsm cho lịch để bàn</li><li>Gia công: cán màng bóng/mờ, ép kim, phủ UV định hình, bế nổi, dập chìm</li></ul><p>Chi phí bản kẽm được chia đều trên số lượng in, nên đơn càng lớn đơn giá càng giảm. Với đơn nhỏ hoặc cần gấp, chúng tôi tư vấn chuyển sang in kỹ thuật số.</p>', 'ph-bold ph-printer', '/assets/images/thumbs/service-in-offset.webp', 1)
  on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, icon = excluded.icon, image_url = excluded.image_url, sort_order = excluded.sort_order;
insert into public.services (slug, name, summary, description, icon, image_url, sort_order) values ('in-flexo', 'In flexo', 'In nổi tốc độ cao trên giấy kraft, carton sóng, màng phim và decal. Mực nhanh khô, phù hợp in logo và nhận diện trên thùng carton, tem nhãn số lượng lớn.', '<p>In Flexo (in nổi) dùng khuôn in bằng photopolymer, cao su hoặc nhựa được khắc bằng ánh sáng UV. Mực Flexo nhanh khô nên in được ở tốc độ cao — đây là lý do kỹ thuật này gần như mặc định cho thùng carton và tem nhãn số lượng lớn.</p><h3>Quy trình 4 bước</h3><ul><li>Chuẩn bị file: thiết kế chuyển sang vector để giữ độ sắc nét</li><li>Làm khuôn in (plate making) bằng ánh sáng UV</li><li>In lên chất liệu bao bì</li><li>Sấy khô, cắt, gấp và hoàn thiện</li></ul><h3>Lưu ý khi thiết kế cho in Flexo</h3><ul><li>Không để chi tiết quá nhỏ hoặc quá phức tạp — dễ mất nét khi in</li><li>Chọn mực phù hợp chất liệu để đảm bảo độ bền màu</li><li>Cân bằng áp lực in để mực không bị lem hoặc thiếu</li><li>Kiểm tra độ dày khuôn và hiệu chỉnh hệ thống kiểm soát màu trước khi chạy sản lượng</li></ul>', 'ph-bold ph-stack', '/assets/images/thumbs/service-in-flexo.webp', 2)
  on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, icon = excluded.icon, image_url = excluded.image_url, sort_order = excluded.sort_order;
insert into public.services (slug, name, summary, description, icon, image_url, sort_order) values ('thiet-ke-bao-bi', 'Thiết kế bao bì', 'Thiết kế hộp giấy, túi xách giấy, tem nhãn và bộ nhận diện bao bì theo đúng quy cách sản xuất. Miễn phí thiết kế cho đơn in tại xưởng.', '<p>Thiết kế bao bì ở In Ấn Thời Đại luôn đi kèm quy cách sản xuất: dao bế, biên dán, nếp gấp và dung sai đều được tính trước, để bản thiết kế in ra đúng như bản duyệt.</p><h3>Nguyên tắc chúng tôi áp dụng</h3><ul><li>Biên dán tối thiểu 25mm để hộp không bị bung</li><li>Nếp gấp phải được tạo rãnh chuẩn, tránh nứt giấy sau cán màng</li><li>Kích thước hộp dư 0.5–1cm so với sản phẩm để dễ đóng gói</li><li>Logo đặt tránh mép gấp, đảm bảo hiển thị đủ trên mọi mặt</li><li>Không lạm dụng nhiều hiệu ứng cùng lúc — vừa đội chi phí vừa dễ nứt bề mặt</li></ul><h3>Hạng mục thiết kế</h3><ul><li>Hộp giấy, hộp cứng nắp nam châm, hộp ngăn kéo, hộp gấp gọn</li><li>Túi xách giấy: quai giấy xoắn, quai dây dù, quai ruy băng, quai PP dẹt</li><li>Tem nhãn decal: giấy, nhựa trong, kim loại, decal chống nước</li><li>Tag treo: oval, tròn, lục giác, vuông/chữ nhật đứng và ngang</li></ul>', 'ph-bold ph-pen-nib', '/assets/images/thumbs/service-thiet-ke-bao-bi.webp', 3)
  on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, icon = excluded.icon, image_url = excluded.image_url, sort_order = excluded.sort_order;
insert into public.services (slug, name, summary, description, icon, image_url, sort_order) values ('gia-cong-sau-in', 'Gia công sau in', 'Cán màng bóng/mờ, ép kim, phủ UV định hình, bế nổi, dập chìm, bồi giấy, gấp dán tự động. Bước quyết định cảm giác cầm của sản phẩm cuối.', '<p>Gia công sau in là bước khiến hai sản phẩm in giống nhau lại cho cảm giác hoàn toàn khác. Xưởng Thời Đại xử lý trọn gói sau in nên không phải chuyển qua nhiều nơi, rút ngắn thời gian giao hàng.</p><h3>Các hạng mục</h3><ul><li><strong>Cán màng bóng / mờ</strong> — bảo vệ bề mặt, tăng độ bền và cảm giác cầm</li><li><strong>Ép kim</strong> — làm nổi logo, tạo điểm nhấn cao cấp, nhiều màu nhũ</li><li><strong>Phủ UV định hình</strong> — tạo độ bóng cục bộ ở phần muốn nhấn</li><li><strong>Bế nổi / dập chìm</strong> — tạo hiệu ứng chạm, chuyên nghiệp và khác biệt</li><li><strong>Bồi giấy Duplex 250–350gsm</strong> lên carton sóng B, C hoặc BE</li><li><strong>Gấp dán</strong> bằng keo tự động hoặc dán tay tuỳ kết cấu hộp</li></ul><h3>Lưu ý</h3><p>Màu in có thể lệch nhẹ giữa giấy thường và giấy đã cán màng — nên duyệt test proof trên đúng chất liệu trước khi chạy sản lượng.</p>', 'ph-bold ph-sparkle', '/assets/images/thumbs/service-gia-cong-sau-in.webp', 4)
  on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, icon = excluded.icon, image_url = excluded.image_url, sort_order = excluded.sort_order;

-- ------------------------------- products -------------------------------
insert into public.products (slug, name, sku, category_slug, price_min, price_max, price_tiers, short_description, description, specs, images, is_featured) values ('hop-giay-trang-carton-29x17x9-5cm', 'Hộp giày trắng Carton 29x17x9.5cm', 'LT009', 'hop-giay', 460000, 2400000, '[{"qty":100,"price":460000},{"qty":200,"price":null},{"qty":300,"price":null},{"qty":400,"price":null},{"qty":500,"price":2400000}]'::jsonb, 'Carton 3 lớp sóng E (N+2X), kích thước 29 x 17 x 9.5 cm, màu trắng hoặc nâu. Nắp gập kiểu tiết kiệm, gấp gọn được để tiết kiệm chi phí lưu kho và vận chuyển.', '<p>Hộp giày trắng Carton 29x17x9.5cm là hộp giày do Công Ty TNHH Công Nghiệp Thời Đại sản xuất trực tiếp tại xưởng, không qua trung gian. Thùng dùng carton 3 lớp sóng e (n+2x), sóng cao 2mm — vừa giữ được độ phẳng và tính thẩm mỹ của bề mặt giấy, vừa chống va đập tốt khi vận chuyển.</p><p>Kiểu hộp: nắp gập kiểu tiết kiệm. Hộp giao ở dạng phôi phẳng, khách tự gấp khi đóng hàng, nhờ đó giảm đáng kể chi phí lưu kho và cước vận chuyển.</p><p>Nhận in logo, nhận diện thương hiệu theo yêu cầu với đơn từ 500 hộp. Đơn trên 500 hộp liên hệ Zalo 0399 466 179 (Ms. Tuyền) để nhận giá ưu đãi. Xưởng nhận sản xuất carton 3 lớp, 5 lớp, 7 lớp với các loại sóng B, C, E theo kích thước riêng của khách.</p>', '{"Chất liệu":"Carton 3 lớp sóng E (N+2X)","Kích thước (D x R x C)":"29 x 17 x 9.5 cm","Màu sắc":"Trắng, nâu","Chiều cao sóng":"2mm","Kiểu hộp":"Nắp gập kiểu tiết kiệm","Kỹ thuật in":"In Flexo 1 màu","Số lượng đặt tối thiểu":"100 hộp","Nhận in theo yêu cầu":"Từ 500 hộp"}'::jsonb, ARRAY['/assets/images/thumbs/shop-img1.png', '/assets/images/thumbs/shop-details-thumb1.png', '/assets/images/thumbs/shop-details-thumb2.png', '/assets/images/thumbs/shop-details-thumb3.png']::text[], true)
  on conflict (slug) do update set name = excluded.name, sku = excluded.sku, category_slug = excluded.category_slug, price_min = excluded.price_min, price_max = excluded.price_max, price_tiers = excluded.price_tiers, short_description = excluded.short_description, description = excluded.description, specs = excluded.specs, images = excluded.images, is_featured = excluded.is_featured;
insert into public.products (slug, name, sku, category_slug, price_min, price_max, price_tiers, short_description, description, specs, images, is_featured) values ('hop-giay-trang-carton-31x19x11cm', 'Hộp giày trắng Carton 31x19x11cm', 'LT004', 'hop-giay', 630000, 3150000, '[{"qty":100,"price":630000},{"qty":200,"price":null},{"qty":300,"price":null},{"qty":400,"price":null},{"qty":500,"price":3150000}]'::jsonb, 'Carton 3 lớp sóng E (N+2X), kích thước 31 x 19 x 11 cm, màu trắng hoặc nâu. Nắp gập kiểu tiết kiệm, gấp gọn được để tiết kiệm chi phí lưu kho và vận chuyển.', '<p>Hộp giày trắng Carton 31x19x11cm là hộp giày do Công Ty TNHH Công Nghiệp Thời Đại sản xuất trực tiếp tại xưởng, không qua trung gian. Thùng dùng carton 3 lớp sóng e (n+2x), sóng cao 2mm — vừa giữ được độ phẳng và tính thẩm mỹ của bề mặt giấy, vừa chống va đập tốt khi vận chuyển.</p><p>Kiểu hộp: nắp gập kiểu tiết kiệm. Hộp giao ở dạng phôi phẳng, khách tự gấp khi đóng hàng, nhờ đó giảm đáng kể chi phí lưu kho và cước vận chuyển.</p><p>Nhận in logo, nhận diện thương hiệu theo yêu cầu với đơn từ 500 hộp. Đơn trên 500 hộp liên hệ Zalo 0399 466 179 (Ms. Tuyền) để nhận giá ưu đãi. Xưởng nhận sản xuất carton 3 lớp, 5 lớp, 7 lớp với các loại sóng B, C, E theo kích thước riêng của khách.</p>', '{"Chất liệu":"Carton 3 lớp sóng E (N+2X)","Kích thước (D x R x C)":"31 x 19 x 11 cm","Màu sắc":"Trắng, nâu","Chiều cao sóng":"2mm","Kiểu hộp":"Nắp gập kiểu tiết kiệm","Kỹ thuật in":"In Flexo 1 màu","Số lượng đặt tối thiểu":"100 hộp","Nhận in theo yêu cầu":"Từ 500 hộp"}'::jsonb, ARRAY['/assets/images/thumbs/shop-img2.png', '/assets/images/thumbs/shop-details-thumb1.png', '/assets/images/thumbs/shop-details-thumb2.png', '/assets/images/thumbs/shop-details-thumb3.png']::text[], true)
  on conflict (slug) do update set name = excluded.name, sku = excluded.sku, category_slug = excluded.category_slug, price_min = excluded.price_min, price_max = excluded.price_max, price_tiers = excluded.price_tiers, short_description = excluded.short_description, description = excluded.description, specs = excluded.specs, images = excluded.images, is_featured = excluded.is_featured;
