insert into public.products (slug, name, sku, category_slug, price_min, price_max, price_tiers, short_description, description, specs, images, is_featured) values ('hop-nap-gai-carton-15x7-5x26-9cm', 'Hộp nắp gài Carton 15x7.5x26.9cm', null, 'hop-nap-gai', 315000, 1625000, '[{"qty":100,"price":315000},{"qty":200,"price":null},{"qty":300,"price":null},{"qty":400,"price":null},{"qty":500,"price":1625000}]'::jsonb, 'Carton 3 lớp sóng E, kích thước 15 x 7.5 x 26.9 cm, màu trắng hoặc nâu. Nắp gài có khoét lỗ xách tay, gấp gọn được để tiết kiệm chi phí lưu kho và vận chuyển.', '<p>Hộp nắp gài Carton 15x7.5x26.9cm là hộp nắp gài do Công Ty TNHH Công Nghiệp Thời Đại sản xuất trực tiếp tại xưởng, không qua trung gian. Thùng dùng carton 3 lớp sóng e, sóng cao 2mm — vừa giữ được độ phẳng và tính thẩm mỹ của bề mặt giấy, vừa chống va đập tốt khi vận chuyển.</p><p>Kiểu hộp: nắp gài có khoét lỗ xách tay. Hộp giao ở dạng phôi phẳng, khách tự gấp khi đóng hàng, nhờ đó giảm đáng kể chi phí lưu kho và cước vận chuyển.</p><p>Nhận in logo, nhận diện thương hiệu theo yêu cầu với đơn từ 500 hộp. Đơn trên 500 hộp liên hệ Zalo 0399 466 179 (Ms. Tuyền) để nhận giá ưu đãi. Xưởng nhận sản xuất carton 3 lớp, 5 lớp, 7 lớp với các loại sóng B, C, E theo kích thước riêng của khách.</p>', '{"Chất liệu":"Carton 3 lớp sóng E","Kích thước (D x R x C)":"15 x 7.5 x 26.9 cm","Màu sắc":"Trắng, nâu","Chiều cao sóng":"2mm","Kiểu hộp":"Nắp gài có khoét lỗ xách tay","Kỹ thuật in":"Không in sẵn — nhận in theo yêu cầu từ 500 hộp","Số lượng đặt tối thiểu":"100 hộp","Nhận in theo yêu cầu":"Từ 500 hộp"}'::jsonb, ARRAY['/assets/images/thumbs/shop-img8.png', '/assets/images/thumbs/shop-details-thumb1.png', '/assets/images/thumbs/shop-details-thumb2.png', '/assets/images/thumbs/shop-details-thumb3.png']::text[], false)
