insert into public.products (slug, name, sku, category_slug, price_min, price_max, price_tiers, short_description, description, specs, images, is_featured) values ('hop-nap-gai-carton-25x25x10cm', 'Hộp nắp gài Carton 25x25x10cm', null, 'hop-nap-gai', 640000, 3150000, '[{"qty":100,"price":640000},{"qty":200,"price":null},{"qty":300,"price":null},{"qty":400,"price":null},{"qty":500,"price":3150000}]'::jsonb, 'Carton 3 lớp sóng E, kích thước 25 x 25 x 10 cm, màu trắng hoặc nâu. Nắp gài tiêu chuẩn, đáy gài, gấp gọn được để tiết kiệm chi phí lưu kho và vận chuyển.', '<p>Hộp nắp gài Carton 25x25x10cm là hộp nắp gài do Công Ty TNHH Công Nghiệp Thời Đại sản xuất trực tiếp tại xưởng, không qua trung gian. Thùng dùng carton 3 lớp sóng e, sóng cao 2mm — vừa giữ được độ phẳng và tính thẩm mỹ của bề mặt giấy, vừa chống va đập tốt khi vận chuyển.</p><p>Kiểu hộp: nắp gài tiêu chuẩn, đáy gài. Hộp giao ở dạng phôi phẳng, khách tự gấp khi đóng hàng, nhờ đó giảm đáng kể chi phí lưu kho và cước vận chuyển.</p><p>Nhận in logo, nhận diện thương hiệu theo yêu cầu với đơn từ 500 hộp. Đơn trên 500 hộp liên hệ Zalo 0399 466 179 (Ms. Tuyền) để nhận giá ưu đãi. Xưởng nhận sản xuất carton 3 lớp, 5 lớp, 7 lớp với các loại sóng B, C, E theo kích thước riêng của khách.</p>', '{"Chất liệu":"Carton 3 lớp sóng E","Kích thước (D x R x C)":"25 x 25 x 10 cm","Màu sắc":"Trắng, nâu","Chiều cao sóng":"2mm","Kiểu hộp":"Nắp gài tiêu chuẩn, đáy gài","Kỹ thuật in":"Không in sẵn — nhận in theo yêu cầu từ 500 hộp","Số lượng đặt tối thiểu":"100 hộp","Nhận in theo yêu cầu":"Từ 500 hộp"}'::jsonb, ARRAY['/assets/images/thumbs/shop-img10.png', '/assets/images/thumbs/shop-details-thumb1.png', '/assets/images/thumbs/shop-details-thumb2.png', '/assets/images/thumbs/shop-details-thumb3.png']::text[], true)
