insert into public.products (slug, name, sku, category_slug, price_min, price_max, price_tiers, short_description, description, specs, images, is_featured) values ('tui-giay-kraft-quai-xoan-in-logo', 'Túi giấy kraft quai xoắn in logo', null, 'tui-xach-giay', 450000, 2250000, '[{"qty":100,"price":450000},{"qty":200,"price":null},{"qty":300,"price":null},{"qty":400,"price":null},{"qty":500,"price":2250000}]'::jsonb, 'Túi giấy kraft, quai xoắn giấy, in logo theo yêu cầu. Dùng đựng hàng thời trang, quà tặng và túi mua sắm bán lẻ.', '<p>Túi giấy kraft quai xoắn in logo là túi giấy đựng hàng do Công Ty TNHH Công Nghiệp Thời Đại sản xuất theo yêu cầu, dùng chất liệu giấy kraft bền dai, quai xoắn giấy chắc chắn, phù hợp làm túi mua sắm bán lẻ, túi đựng quà tặng hoặc túi thương hiệu cho cửa hàng.</p><p>Nhận in logo, nhận diện thương hiệu theo yêu cầu thiết kế. Liên hệ Zalo 0399 466 179 (Ms. Tuyền) hoặc gọi hotline 0938 676 746 để được tư vấn quy cách phù hợp và nhận báo giá chính thức.</p>', '{"Chất liệu":"Giấy kraft","Kiểu quai":"Quai xoắn giấy","Kỹ thuật in":"In offset hoặc Flexo theo yêu cầu","Màu sắc":"Theo yêu cầu thiết kế"}'::jsonb, ARRAY['/assets/images/thumbs/shop-img1.png', '/assets/images/thumbs/shop-details-thumb1.png', '/assets/images/thumbs/shop-details-thumb2.png', '/assets/images/thumbs/shop-details-thumb3.png']::text[], false)
  on conflict (slug) do update set name = excluded.name, sku = excluded.sku, category_slug = excluded.category_slug, price_min = excluded.price_min, price_max = excluded.price_max, price_tiers = excluded.price_tiers, short_description = excluded.short_description, description = excluded.description, specs = excluded.specs, images = excluded.images, is_featured = excluded.is_featured;
insert into public.products (slug, name, sku, category_slug, price_min, price_max, price_tiers, short_description, description, specs, images, is_featured) values ('tui-giay-trang-can-mang-bong', 'Túi giấy trắng cán màng bóng', null, 'tui-xach-giay', 520000, 2600000, '[{"qty":100,"price":520000},{"qty":200,"price":null},{"qty":300,"price":null},{"qty":400,"price":null},{"qty":500,"price":2600000}]'::jsonb, 'Túi giấy couche trắng, cán màng bóng, quai dẹt. Phù hợp làm túi đựng mỹ phẩm và quà tặng cao cấp.', '<p>Túi giấy trắng cán màng bóng là túi giấy couche cao cấp do Công Ty TNHH Công Nghiệp Thời Đại sản xuất theo yêu cầu, bề mặt cán màng bóng tăng độ bền và thẩm mỹ, phù hợp làm túi đựng mỹ phẩm, quà tặng và các mặt hàng cần hình ảnh sang trọng.</p><p>Nhận in logo, nhận diện thương hiệu theo yêu cầu thiết kế. Liên hệ Zalo 0399 466 179 (Ms. Tuyền) hoặc gọi hotline 0938 676 746 để được tư vấn quy cách phù hợp và nhận báo giá chính thức.</p>', '{"Chất liệu":"Giấy couche cán màng bóng","Kiểu quai":"Quai dẹt","Kỹ thuật in":"In offset","Màu sắc":"Theo yêu cầu thiết kế"}'::jsonb, ARRAY['/assets/images/thumbs/shop-img2.png', '/assets/images/thumbs/shop-details-thumb1.png', '/assets/images/thumbs/shop-details-thumb2.png', '/assets/images/thumbs/shop-details-thumb3.png']::text[], false)
  on conflict (slug) do update set name = excluded.name, sku = excluded.sku, category_slug = excluded.category_slug, price_min = excluded.price_min, price_max = excluded.price_max, price_tiers = excluded.price_tiers, short_description = excluded.short_description, description = excluded.description, specs = excluded.specs, images = excluded.images, is_featured = excluded.is_featured;
insert into public.products (slug, name, sku, category_slug, price_min, price_max, price_tiers, short_description, description, specs, images, is_featured) values ('tui-giay-couche-quai-det-in-offset', 'Túi giấy couche quai dẹt in offset', null, 'tui-xach-giay', 480000, 2450000, '[{"qty":100,"price":480000},{"qty":200,"price":null},{"qty":300,"price":null},{"qty":400,"price":null},{"qty":500,"price":2450000}]'::jsonb, 'Túi giấy couche, in offset nhiều màu, quai dẹt. Dùng làm túi thương hiệu cho shop thời trang, mỹ phẩm.', '<p>Túi giấy couche quai dẹt in offset do Công Ty TNHH Công Nghiệp Thời Đại sản xuất theo yêu cầu, in offset nhiều màu sắc nét, quai dẹt chắc chắn, phù hợp làm túi thương hiệu cho shop thời trang, mỹ phẩm và cửa hàng bán lẻ.</p><p>Nhận in logo, nhận diện thương hiệu theo yêu cầu thiết kế. Liên hệ Zalo 0399 466 179 (Ms. Tuyền) hoặc gọi hotline 0938 676 746 để được tư vấn quy cách phù hợp và nhận báo giá chính thức.</p>', '{"Chất liệu":"Giấy couche","Kiểu quai":"Quai dẹt","Kỹ thuật in":"In offset","Màu sắc":"Theo yêu cầu thiết kế"}'::jsonb, ARRAY['/assets/images/thumbs/shop-img3.png', '/assets/images/thumbs/shop-details-thumb1.png', '/assets/images/thumbs/shop-details-thumb2.png', '/assets/images/thumbs/shop-details-thumb3.png']::text[], false)
