insert into public.products (slug, name, sku, category_slug, price_min, price_max, price_tiers, short_description, description, specs, images, is_featured) values ('tui-giay-kraft-nau-quai-giay-tu-nhien', 'Túi giấy kraft nâu quai giấy tự nhiên', null, 'tui-xach-giay', 380000, 1900000, '[{"qty":100,"price":380000},{"qty":200,"price":null},{"qty":300,"price":null},{"qty":400,"price":null},{"qty":500,"price":1900000}]'::jsonb, 'Túi giấy kraft nâu tự nhiên, quai giấy, phong cách mộc mạc. Phù hợp đóng gói thực phẩm, quà handmade.', '<p>Túi giấy kraft nâu quai giấy tự nhiên do Công Ty TNHH Công Nghiệp Thời Đại sản xuất theo yêu cầu, giữ nguyên màu giấy kraft tự nhiên, phong cách mộc mạc, phù hợp đóng gói thực phẩm, quà tặng handmade và các mặt hàng thân thiện môi trường.</p><p>Nhận in logo, nhận diện thương hiệu theo yêu cầu thiết kế. Liên hệ Zalo 0399 466 179 (Ms. Tuyền) hoặc gọi hotline 0938 676 746 để được tư vấn quy cách phù hợp và nhận báo giá chính thức.</p>', '{"Chất liệu":"Giấy kraft nâu","Kiểu quai":"Quai giấy","Kỹ thuật in":"In Flexo 1 màu theo yêu cầu","Màu sắc":"Nâu tự nhiên"}'::jsonb, ARRAY['/assets/images/thumbs/shop-img4.png', '/assets/images/thumbs/shop-details-thumb1.png', '/assets/images/thumbs/shop-details-thumb2.png', '/assets/images/thumbs/shop-details-thumb3.png']::text[], false)
