insert into public.products (slug, name, sku, category_slug, price_min, price_max, price_tiers, short_description, description, specs, images, is_featured) values ('tui-giay-can-mang-mo-co-ruy-bang', 'Túi giấy cán màng mờ có ruy băng', null, 'tui-xach-giay', 650000, 3150000, '[{"qty":100,"price":650000},{"qty":200,"price":null},{"qty":300,"price":null},{"qty":400,"price":null},{"qty":500,"price":3150000}]'::jsonb, 'Túi giấy cán màng mờ, quai ruy băng vải. Dùng làm túi quà tặng cao cấp, túi đựng mỹ phẩm.', '<p>Túi giấy cán màng mờ có ruy băng do Công Ty TNHH Công Nghiệp Thời Đại sản xuất theo yêu cầu, bề mặt cán màng mờ sang trọng, quai ruy băng vải, phù hợp làm túi quà tặng cao cấp và túi đựng mỹ phẩm thương hiệu.</p><p>Nhận in logo, nhận diện thương hiệu theo yêu cầu thiết kế. Liên hệ Zalo 0399 466 179 (Ms. Tuyền) hoặc gọi hotline 0938 676 746 để được tư vấn quy cách phù hợp và nhận báo giá chính thức.</p>', '{"Chất liệu":"Giấy couche cán màng mờ","Kiểu quai":"Quai ruy băng vải","Kỹ thuật in":"In offset","Màu sắc":"Theo yêu cầu thiết kế"}'::jsonb, ARRAY['/assets/images/thumbs/shop-img5.png', '/assets/images/thumbs/shop-details-thumb1.png', '/assets/images/thumbs/shop-details-thumb2.png', '/assets/images/thumbs/shop-details-thumb3.png']::text[], false)
