insert into public.products (slug, name, sku, category_slug, price_min, price_max, price_tiers, short_description, description, specs, images, is_featured) values ('hop-qua-nap-roi-giay-my-thuat', 'Hộp quà nắp rời giấy mỹ thuật', null, 'hop-qua-tang', 1650000, 8100000, '[{"qty":100,"price":1650000},{"qty":200,"price":null},{"qty":300,"price":null},{"qty":400,"price":null},{"qty":500,"price":8100000}]'::jsonb, 'Hộp quà nắp rời, bọc giấy mỹ thuật, kiểu dáng cổ điển. Dùng làm hộp quà Tết, quà doanh nghiệp.', '<p>Hộp quà nắp rời giấy mỹ thuật do Công Ty TNHH Công Nghiệp Thời Đại sản xuất theo yêu cầu, bọc giấy mỹ thuật, kiểu dáng nắp rời cổ điển, phù hợp làm hộp quà Tết, quà tặng doanh nghiệp và quà tặng sự kiện.</p><p>Nhận in logo, nhận diện thương hiệu theo yêu cầu thiết kế. Liên hệ Zalo 0399 466 179 (Ms. Tuyền) hoặc gọi hotline 0938 676 746 để được tư vấn quy cách phù hợp và nhận báo giá chính thức.</p>', '{"Chất liệu":"Giấy mỹ thuật bồi carton","Kiểu hộp":"Nắp rời","Gia công":"Theo yêu cầu thiết kế","Màu sắc":"Theo yêu cầu thiết kế"}'::jsonb, ARRAY['/assets/images/thumbs/shop-img6.png', '/assets/images/thumbs/shop-details-thumb1.png', '/assets/images/thumbs/shop-details-thumb2.png', '/assets/images/thumbs/shop-details-thumb3.png']::text[], false)
