insert into public.products (slug, name, sku, category_slug, price_min, price_max, price_tiers, short_description, description, specs, images, is_featured) values ('hop-qua-day-khay-nhua-dinh-hinh', 'Hộp quà tặng đáy khay nhựa định hình', null, 'hop-qua-tang', 2350000, 11600000, '[{"qty":100,"price":2350000},{"qty":200,"price":null},{"qty":300,"price":null},{"qty":400,"price":null},{"qty":500,"price":11600000}]'::jsonb, 'Hộp quà có khay nhựa định hình bên trong, cố định sản phẩm chắc chắn. Dùng cho quà tặng nhiều món.', '<p>Hộp quà tặng đáy khay nhựa định hình do Công Ty TNHH Công Nghiệp Thời Đại sản xuất theo yêu cầu, khay nhựa bên trong được định hình theo sản phẩm, giữ cố định chắc chắn khi vận chuyển, phù hợp cho set quà tặng nhiều món.</p><p>Nhận in logo, nhận diện thương hiệu theo yêu cầu thiết kế. Liên hệ Zalo 0399 466 179 (Ms. Tuyền) hoặc gọi hotline 0938 676 746 để được tư vấn quy cách phù hợp và nhận báo giá chính thức.</p>', '{"Chất liệu":"Giấy bồi carton, khay nhựa định hình","Kiểu hộp":"Nắp rời","Gia công":"Theo yêu cầu thiết kế","Màu sắc":"Theo yêu cầu thiết kế"}'::jsonb, ARRAY['/assets/images/thumbs/shop-img9.png', '/assets/images/thumbs/shop-details-thumb1.png', '/assets/images/thumbs/shop-details-thumb2.png', '/assets/images/thumbs/shop-details-thumb3.png']::text[], false)
