insert into public.products (slug, name, sku, category_slug, price_min, price_max, price_tiers, short_description, description, specs, images, is_featured) values ('tem-nhan-decal-giay-in-offset', 'Tem nhãn decal giấy in offset', null, 'tem-nhan-decal', 180000, 850000, '[{"qty":100,"price":180000},{"qty":200,"price":null},{"qty":300,"price":null},{"qty":400,"price":null},{"qty":500,"price":850000}]'::jsonb, 'Decal giấy in offset nhiều màu, phổ biến cho tem nhãn sản phẩm. Dùng cho bánh kẹo, mứt Tết, hàng tiêu dùng.', '<p>Tem nhãn decal giấy in offset do Công Ty TNHH Công Nghiệp Thời Đại sản xuất theo yêu cầu, in offset đa dạng màu sắc và thông tin sản phẩm, là lựa chọn phổ biến nhất cho tem nhãn bánh kẹo, mứt Tết và hàng tiêu dùng.</p><p>Nhận in logo, nhận diện thương hiệu theo yêu cầu thiết kế. Liên hệ Zalo 0399 466 179 (Ms. Tuyền) hoặc gọi hotline 0938 676 746 để được tư vấn quy cách phù hợp và nhận báo giá chính thức.</p>', '{"Chất liệu":"Decal giấy","Kỹ thuật in":"In offset","Hình thức":"Cuộn hoặc tờ rời theo yêu cầu","Ứng dụng":"Tem nhãn sản phẩm tiêu dùng"}'::jsonb, ARRAY['/assets/images/thumbs/shop-img11.png', '/assets/images/thumbs/shop-details-thumb1.png', '/assets/images/thumbs/shop-details-thumb2.png', '/assets/images/thumbs/shop-details-thumb3.png']::text[], false)
