insert into public.products (slug, name, sku, category_slug, price_min, price_max, price_tiers, short_description, description, specs, images, is_featured) values ('decal-nhua-trong-suot-cat-be', 'Decal nhựa trong suốt cắt bế', null, 'tem-nhan-decal', 320000, 1550000, '[{"qty":100,"price":320000},{"qty":200,"price":null},{"qty":300,"price":null},{"qty":400,"price":null},{"qty":500,"price":1550000}]'::jsonb, 'Decal nhựa trong suốt, cắt bế theo khuôn. Phù hợp cho sản phẩm cần thể hiện sự sang trọng như rượu, trà.', '<p>Decal nhựa trong suốt cắt bế do Công Ty TNHH Công Nghiệp Thời Đại sản xuất theo yêu cầu, chất liệu nhựa trong suốt, cắt bế đúng theo khuôn thiết kế, phù hợp cho sản phẩm cần thể hiện sự sang trọng như rượu, trà, bánh mứt cao cấp.</p><p>Nhận in logo, nhận diện thương hiệu theo yêu cầu thiết kế. Liên hệ Zalo 0399 466 179 (Ms. Tuyền) hoặc gọi hotline 0938 676 746 để được tư vấn quy cách phù hợp và nhận báo giá chính thức.</p>', '{"Chất liệu":"Decal nhựa trong suốt","Kỹ thuật in":"In offset hoặc kỹ thuật số","Hình thức":"Cắt bế theo khuôn","Ứng dụng":"Sản phẩm cao cấp: rượu, trà, mỹ phẩm"}'::jsonb, ARRAY['/assets/images/thumbs/shop-img12.png', '/assets/images/thumbs/shop-details-thumb1.png', '/assets/images/thumbs/shop-details-thumb2.png', '/assets/images/thumbs/shop-details-thumb3.png']::text[], false)
