insert into public.products (slug, name, sku, category_slug, price_min, price_max, price_tiers, short_description, description, specs, images, is_featured) values ('tem-nhan-decal-kim-loai-anh-vang', 'Tem nhãn decal kim loại ánh vàng', null, 'tem-nhan-decal', 450000, 2150000, '[{"qty":100,"price":450000},{"qty":200,"price":null},{"qty":300,"price":null},{"qty":400,"price":null},{"qty":500,"price":2150000}]'::jsonb, 'Decal kim loại ánh vàng/bạc, vẻ ngoài lấp lánh sang trọng. Dùng cho trà, cà phê, rượu vang, quà cao cấp.', '<p>Tem nhãn decal kim loại ánh vàng do Công Ty TNHH Công Nghiệp Thời Đại sản xuất theo yêu cầu, mang vẻ đẹp lấp lánh và sang trọng, thường dùng cho trà, cà phê, rượu vang và các dòng quà tặng cao cấp.</p><p>Nhận in logo, nhận diện thương hiệu theo yêu cầu thiết kế. Liên hệ Zalo 0399 466 179 (Ms. Tuyền) hoặc gọi hotline 0938 676 746 để được tư vấn quy cách phù hợp và nhận báo giá chính thức.</p>', '{"Chất liệu":"Decal kim loại (vàng, bạc)","Kỹ thuật in":"In offset","Hình thức":"Cuộn hoặc tờ rời theo yêu cầu","Ứng dụng":"Sản phẩm cao cấp: trà, cà phê, rượu vang"}'::jsonb, ARRAY['/assets/images/thumbs/shop-img1.png', '/assets/images/thumbs/shop-details-thumb1.png', '/assets/images/thumbs/shop-details-thumb2.png', '/assets/images/thumbs/shop-details-thumb3.png']::text[], false)
