insert into public.products (slug, name, sku, category_slug, price_min, price_max, price_tiers, short_description, description, specs, images, is_featured) values ('decal-chong-nuoc-dan-chai-lo', 'Decal chống nước dán chai lọ', null, 'tem-nhan-decal', 290000, 1400000, '[{"qty":100,"price":290000},{"qty":200,"price":null},{"qty":300,"price":null},{"qty":400,"price":null},{"qty":500,"price":1400000}]'::jsonb, 'Decal chống nước, độ bám dính cao. Phù hợp dán chai lọ mỹ phẩm, thực phẩm cần bảo quản lạnh/ẩm.', '<p>Decal chống nước dán chai lọ do Công Ty TNHH Công Nghiệp Thời Đại sản xuất theo yêu cầu, chất liệu chống nước, độ bám dính cao, phù hợp dán chai lọ mỹ phẩm, thực phẩm và các sản phẩm cần bảo quản trong môi trường ẩm hoặc lạnh.</p><p>Nhận in logo, nhận diện thương hiệu theo yêu cầu thiết kế. Liên hệ Zalo 0399 466 179 (Ms. Tuyền) hoặc gọi hotline 0938 676 746 để được tư vấn quy cách phù hợp và nhận báo giá chính thức.</p>', '{"Chất liệu":"Decal chống nước","Kỹ thuật in":"In offset hoặc kỹ thuật số","Hình thức":"Cuộn hoặc tờ rời theo yêu cầu","Ứng dụng":"Chai lọ mỹ phẩm, thực phẩm"}'::jsonb, ARRAY['/assets/images/thumbs/shop-img2.png', '/assets/images/thumbs/shop-details-thumb1.png', '/assets/images/thumbs/shop-details-thumb2.png', '/assets/images/thumbs/shop-details-thumb3.png']::text[], false)
